## 00_config.R -- load the data-driven signature / class / rule tables.
##
## All biological logic lives in module/nlr_signatures.tsv, module/nlr_classes.tsv and
## module/nlr_subclass_rules.tsv, which are generated by module/build_signature_table.py.
## Nothing in this file hardcodes a signature accession.

## Component packages only. The tidyverse meta-package is deliberately not required:
## it adds an install dependency without adding capability.
suppressPackageStartupMessages({
  library(dplyr)
  library(tidyr)
  library(readr)
  library(stringr)
  library(tibble)
  library(purrr)
  library(ggplot2)
})

options(dplyr.summarise.inform = FALSE)

read_tsv_config <- function(path, what) {
  if (!file.exists(path)) stop("missing ", what, ": ", path, call. = FALSE)
  ## Comment lines are stripped by hand rather than with readr's `comment = "#"`.
  ## readr applies `comment` ANYWHERE in a line, so it silently truncated every hex
  ## colour: "#FED9A6" became "" and took the following column with it. Only lines
  ## that START with # are comments here.
  lines <- readr::read_lines(path, progress = FALSE)
  lines <- lines[!grepl("^\\s*#", lines)]
  ## Everything is read as character and converted explicitly by the caller. Letting readr
  ## guess types produced spurious warnings -- the hit-count columns are populated only for
  ## the curated rows, so it guessed `double` and then choked on the blanks. A warning that
  ## is always present is a warning nobody reads.
  ##
  ## quote = "" because InterPro entry descriptions contain bare double quotes,
  ## e.g. IPR036390 '"Winged helix" DNA-binding domain'.
  readr::read_tsv(I(lines), show_col_types = FALSE, quote = "",
                  col_types = readr::cols(.default = readr::col_character()),
                  progress = FALSE, na = character()) %>%
    mutate(across(where(is.character), ~ dplyr::na_if(.x, "")))
}

load_config <- function(signatures, classes, subclass_rules, entry_list) {
  sig <- read_tsv_config(signatures, "signature table")
  cls <- read_tsv_config(classes, "class table")
  rul <- read_tsv_config(subclass_rules, "subclass rule table")

  required <- c("signature", "database", "ipr_entry", "ipr_short_name",
                "ipr_description", "domain_class", "subclass_evidence")
  missing <- setdiff(required, names(sig))
  if (length(missing)) {
    stop("signature table is missing column(s): ", paste(missing, collapse = ", "),
         call. = FALSE)
  }

  ## Every class referenced by a signature must exist in the class table, or the
  ## merge and region logic would silently drop annotations.
  orphan <- setdiff(unique(sig$domain_class), cls$domain_class)
  if (length(orphan)) {
    stop("signature table references undefined class(es): ",
         paste(orphan, collapse = ", "), call. = FALSE)
  }

  cls <- cls %>%
    mutate(precedence = as.integer(precedence),
           drop_after = tolower(drop_after) %in% c("yes", "true", "1"))

  ## InterPro entry list: ENTRY_AC / ENTRY_TYPE / ENTRY_NAME. With InterProScan 6 TSV
  ## input the entry name already arrives in column 13, so this join now only
  ## supplies ENTRY_TYPE plus a name of last resort.
  entries <- read_tsv_config(entry_list, "InterPro entry list")
  if (!all(c("ENTRY_AC", "ENTRY_TYPE", "ENTRY_NAME") %in% names(entries))) {
    stop("entry list must have ENTRY_AC, ENTRY_TYPE and ENTRY_NAME columns", call. = FALSE)
  }

  list(
    signatures = sig,
    classes    = cls,
    rules      = rul,
    entries    = entries,
    ## lookup helpers
    class_of   = setNames(sig$domain_class, sig$signature),
    region_of  = setNames(cls$region, cls$domain_class),
    merge_of   = setNames(cls$merge_group, cls$domain_class),
    prec_of    = setNames(cls$precedence, cls$domain_class),
    drop_after = cls$domain_class[cls$drop_after],
    simple_of  = setNames(cls$simple_code, cls$domain_class),
    colour_of  = setNames(cls$colour, cls$domain_class),
    shape_of   = setNames(cls$shape, cls$domain_class)
  )
}

## Region order defines arbitration. NB-ARC is the anchor and is never trimmed.
## N-terminal regions are truncated to end before it; LRR is truncated to start
## after it; C-JID is truncated to start after the LRR.
REGION_NTERM   <- c("TIR", "CC", "RPW8", "R1")
## Both NB-ARC and a bare P-loop anchor the arbitration: they are the same
## nucleotide-binding core, differing only in how much evidence supports them, so an
## N-terminal region must end before either and the LRR must start after either.
REGION_ANCHOR  <- c("NB-ARC", "PLOOP")
REGION_AFTER   <- "LRR"
REGION_TERMINAL <- "C-JID"
REGION_ID      <- "ID"

## C-JID starts one residue after the LRR ends, so regions are strictly disjoint.
## Set to 0 to make C-JID start exactly at the LRR end instead.
CJID_LRR_OFFSET <- 1L

## FIMO motif number -> name. Motif identity comes from the bundled meme.xml
## (NLR Annotator), not from InterPro, so it is defined here rather than in the
## signature table.
MEME_MOTIF_NAMES <- c(
  "1" = "P-loop",   "2" = "RNBS-D", "3" = "GLPL",    "4" = "Kin-2",
  "5" = "RNBS-B",   "6" = "RNBS-A", "7" = "MHD",     "8" = "linker",
  "9" = "LRR motif1 LDL",           "10" = "RNBS-C", "11" = "LRR motif 11",
  "12" = "NB-ARC motif 12",         "13" = "TIR-3",
  "14" = "monocot NLR CC-NBARC linker",              "15" = "TIR-2",
  "16" = "CC-EDVID", "17" = "CC",   "18" = "TIR-1",  "19" = "LRR motif 19",
  "20" = "monocot NLR LRR"
)

## The NB-ARC motifs in their canonical N-to-C order. A decrease in this index
## along a sequence marks the start of a new NB-ARC.
NBARC_MOTIF_ORDER <- c(
  "P-loop" = 1, "RNBS-A" = 2, "Kin-2" = 3, "RNBS-B" = 4, "RNBS-C" = 5,
  "GLPL" = 6, "NB-ARC motif 12" = 7, "RNBS-D" = 8, "linker" = 9, "MHD" = 10
)

## Motifs needing a higher score before they count as degenerate-NLR evidence.
MOTIF_HIGH_SCORE <- c("MHD" = 85, "linker" = 85)
FIMO_MIN_SCORE   <- 60
FIMO_MAX_QVALUE  <- 0.01

## Signatures whose InterProScan record carries neither an InterPro entry nor a
## signature description. Only these need a name supplied locally; every other
## name now comes from TSV column 6 or 13. Generated by
## build_signature_table.py as needs_name_fallback == "yes".
NAME_FALLBACK <- c(
  "G3DSA:1.20.5.4130" = "Rx N-terminal domain",
  "G3DSA:1.10.533.20" = "CARD-like domain",
  "G3DSA:3.30.70.100" = "HMA",
  "G3DSA:3.10.20.370" = "Transposon-related domain",
  "G3DSA:1.10.340.70" = "Transposon-related domain",
  "cd00200"           = "WD40 repeat",
  "cd02947"           = "Thioredoxin-like domain",
  "cd02989"           = "Other",
  "PR00364"           = "Disease resistance protein signature"
)

## Repeat-type signatures suppressed from the published GFF3 so that per-repeat
## LRR rows do not swamp the annotation. Derived from the class table at run time
## for LRR, plus the FIMO LRR motifs.
gff3_noise_signatures <- function(cfg) {
  lrr <- cfg$signatures$signature[cfg$signatures$domain_class == "LRR"]
  motifs <- c("Motif 9", "Motif 11", "Motif 19", "Motif 20")
  unique(c(lrr, motifs))
}
